<template>
  <div class="processing-analytics">
    <loader :is-visible="isLoading"></loader>
    <div class="widgets-grid">
      <AgentPerformance v-if="isShowAgentPerformence" :AgentPerformenceData="AgentPerformenceData" />

      <FlagReason v-if="isShowAgentPerformence" :FlagResonData="FlagResonData" :FlagReason="FlagReason"
        :FlagRecords="FlagRecords"></FlagReason>

      <FlagRecords v-if="isShowAgentPerformence" :FlagRecordsData="FlagRecordsData" :State="State"
        :FlagRecords="FlagRecord"></FlagRecords>

      <WorkDateStatusReport v-if="isShowAgentPerformence"></WorkDateStatusReport>
    </div>
  </div>
</template>

<script>
import { analyticsService } from '../../../services/analyticsService';
import AgentPerformance from './widgets/AgentPerformance.vue';
import FlagReason from './widgets/FlagReason.vue';
import FlagRecords from './widgets/FlagRecords.vue';
import WorkDateStatusReport from './widgets/WorkDateStatusReport.vue';

export default {
  name: 'ProcessingAnalytics',
  components: {
    AgentPerformance,
    FlagReason,
    FlagRecords,
    WorkDateStatusReport

  },
  data() {
    return {
      AgentPerformenceData: [],
      GeographicDistributionData: [],
      GetQuarterlyBillingStatsData: [],
      isShowAgentPerformence: false,
      isShowGeographicDistribution: false,
      isLoading: false,

      FlagResonData: [],
      FlagReason: [],
      FlagRecords: [],

      FlagRecordsData: [],
      State: [],
      FlagRecord: [],


    }
  },

  created: async function () {
    debugger
    const vm = this;
    vm.isLoading = true;

    try {
      await vm.AgentPerformence();
      await vm.loadFlagReasonData();
      await vm.loadFlagRecordsData();
    } catch (err) {
      console.error(err);
    } finally {
      vm.isLoading = false; // ✅ hide loader after page is ready
    }
  },
  methods: {

    async AgentPerformence() {
      var vm = this;

      try {

        const response = await analyticsService.GetAgentPerformenceData();
        if (response && response.data && response.data.result) {

          vm.AgentPerformenceData = response.data.result;
          vm.isShowAgentPerformence = true;

        }
      } catch (error) {
        console.error('Error loading total revenue trend:', error);
      } finally {
        //this.loading = false;
      }
    },
    async loadFlagReasonData() {
      //this.isLoading = true;      
      try {
        const response = await analyticsService.GetFlagReasonData();

        if (response?.data?.result) {

          let result = response.data.result;

          if (typeof result === 'string') {
            result = JSON.parse(result);
          }

          if (Array.isArray(result) && typeof result[0] === 'string') {
            result = JSON.parse(result[0]);
          }

          const dataArray = result.Data || [];

          this.FlagResonData = dataArray;
          this.FlagReason = dataArray.map(x => x.flag_reason);
          this.FlagRecords = dataArray.map(x => x.FlagRecords);

          //this.drawChart();
        }
      } catch (error) {
        console.error('Error loading flag reason data:', error);
      } finally {
        //this.isLoading = false;
      }
    },

    async loadFlagRecordsData() {
      debugger
      //this.isLoading = true;

      try {
        const response = await analyticsService.GetFlagRecorsData();

        if (response?.data?.result) {

          let result = response.data.result;

          if (typeof result === 'string') {
            result = JSON.parse(result);
          }

          if (Array.isArray(result) && typeof result[0] === 'string') {
            result = JSON.parse(result[0]);
          }

          const dataArray = result.Data || [];

          this.FlagRecordsData = dataArray;
          this.State = dataArray.map(x => x.state);
          this.FlagRecord = dataArray.map(x => x.FlagRecords);

          //this.drawChart();
        }

      } catch (error) {
        console.error('Error loading flag records:', error);
      } finally {
        //this.isLoading = false;
      }
    },

  }
};
</script>

<style scoped>
.processing-analytics {
  width: 100%;
}

.widgets-grid {
  display: grid;
  /* grid-template-columns: repeat(auto-fit, minmax(400px, 1fr)); */
  gap: 20px;
}
</style>